INSERT IGNORE INTO `tours` (`slug`, `title`, `destination`, `destination_slug`, `category`, `category_slug`, `duration`, `duration_band`, `price`, `rating`, `reviews`, `language`, `image_url`, `gallery`, `summary`, `overview`, `highlights`, `discover`, `itinerary`, `meeting_point`, `included`, `excluded`, `important`, `faqs`, `trending`, `seasonal`, `popular`, `status`)
VALUES
  ('south-goa-temple-run', 'South Goa Temple Run', 'South Goa Temple Run', 'south-goa-temple-run', 'Curated Journeys', 'curated-journeys', '3 days', 'Multi-day', 0, 0, 0, '["English","Hindi"]', '/destinations/south-goa/mangeshi-premium.png', '["/destinations/south-goa/mangeshi-premium.png","/destinations/south-goa/Sapthakoteshwar-upscaled.webp"]', 'Goa''s sacred temples, far from the beaches.', 'Follow a carefully paced route through Nageshi, Mangeshi and Shanta Durga, Saptakoteshwar, Bhairoba Goa.', '["Nageshi, Mangeshi and Shanta Durga","Saptakoteshwar","Bhairoba Goa"]', '["Begin with two of Goa''s best-known temples and their distinctive architecture.","Spend the day on the history and story of this ancient Shiva temple.","Visit the local shrine, learn about village deity traditions, and wrap up the trip."]', '[{"time":"Day 1","title":"Nageshi, Mangeshi and Shanta Durga","detail":"Begin with two of Goa''s best-known temples and their distinctive architecture."},{"time":"Day 2","title":"Saptakoteshwar","detail":"Spend the day on the history and story of this ancient Shiva temple."},{"time":"Day 3","title":"Bhairoba Goa","detail":"Visit the local shrine, learn about village deity traditions, and wrap up the trip."}]', 'Meeting points, transfers and departure details are confirmed after enquiry.', '["Route planning","Heritage itinerary","Local context notes"]', '["Accommodation","Meals","Travel between locations"]', '["Opening hours and access can change","Please confirm dates before booking"]', '[{"q":"How large are the groups?","a":"Most experiences run with 6 to 12 travellers so that everyone can hear the guide and ask questions. Private departures are available on request."},{"q":"Is the route accessible?","a":"Routes vary. Several walks use uneven lanes and steps. Tell us your requirements when you enquire and we will suggest a suitable route or adapt the walk."},{"q":"What happens if it rains?","a":"Walks run in light rain with covered stops built in. If conditions are unsafe we reschedule or refund in full."}]', 0, NULL, 1, 'published'),
