  ('western-maharashtra-heritage', 'Western Maharashtra Heritage', 'Western Maharashtra Heritage', 'western-maharashtra-heritage', 'Curated Journeys', 'curated-journeys', '2 days (please confirm)', 'Multi-day', 0, 0, 0, '["English","Hindi"]', '/destinations/western-maharashtra/Satara-upscaled.webp', '["/destinations/western-maharashtra/Satara-upscaled.webp","/destinations/western-maharashtra/wai-upscaled.webp","/destinations/western-maharashtra/Kolhapur-upscaled.webp","/destinations/western-maharashtra/Narsobachi%20Wadi-upscaled.webp"]', 'The Maratha heartland, town by town.', 'Follow a carefully paced route through Pune, Wai and Satara, Kolhapur, Narsobachi Wadi and Karad.', '["Pune, Wai and Satara","Kolhapur, Narsobachi Wadi and Karad"]', '["Start with the old city, then travel to the ghats and hill towns of the Krishna valley.","Visit the temple city, the riverside shrine, and end at the confluence town of Karad."]', '[{"time":"Day 1","title":"Pune, Wai and Satara","detail":"Start with the old city, then travel to the ghats and hill towns of the Krishna valley."},{"time":"Day 2","title":"Kolhapur, Narsobachi Wadi and Karad","detail":"Visit the temple city, the riverside shrine, and end at the confluence town of Karad."}]', 'Meeting points, transfers and departure details are confirmed after enquiry.', '["Route planning","Heritage itinerary","Local context notes"]', '["Accommodation","Meals","Travel between locations"]', '["Opening hours and access can change","Please confirm dates before booking"]', '[{"q":"How large are the groups?","a":"Most experiences run with 6 to 12 travellers so that everyone can hear the guide and ask questions. Private departures are available on request."},{"q":"Is the route accessible?","a":"Routes vary. Several walks use uneven lanes and steps. Tell us your requirements when you enquire and we will suggest a suitable route or adapt the walk."},{"q":"What happens if it rains?","a":"Walks run in light rain with covered stops built in. If conditions are unsafe we reschedule or refund in full."}]', 0, NULL, 1, 'published'),
  ('northern-karnataka-heritage', 'Northern Karnataka Heritage', 'Northern Karnataka Heritage', 'northern-karnataka-heritage', 'Curated Journeys', 'curated-journeys', '3-4 days', 'Multi-day', 0, 0, 0, '["English","Hindi"]', '/destinations/northern-karnataka/Badami-premium.png', '["/destinations/northern-karnataka/Badami-premium.png","/destinations/northern-karnataka/Aihole-premium.png","/destinations/northern-karnataka/Pattadakal-upscaled.webp"]', 'Where Indian temple architecture began.', 'Follow a carefully paced route through Badami, Aihole, Pattadakal, A flexible day.', '["Badami","Aihole","Pattadakal","A flexible day"]', '["Explore the cave temples and the old Chalukyan capital.","See the early experimental temples, often called the cradle of temple architecture.","Finish at the UNESCO-listed temple complex.","Revisit sites or explore nearby villages."]', '[{"time":"Day 1","title":"Badami","detail":"Explore the cave temples and the old Chalukyan capital."},{"time":"Day 2","title":"Aihole","detail":"See the early experimental temples, often called the cradle of temple architecture."},{"time":"Day 3","title":"Pattadakal","detail":"Finish at the UNESCO-listed temple complex."},{"time":"Day 4 (optional)","title":"A flexible day","detail":"Revisit sites or explore nearby villages."}]', 'Meeting points, transfers and departure details are confirmed after enquiry.', '["Route planning","Heritage itinerary","Local context notes"]', '["Accommodation","Meals","Travel between locations"]', '["Opening hours and access can change","Please confirm dates before booking"]', '[{"q":"How large are the groups?","a":"Most experiences run with 6 to 12 travellers so that everyone can hear the guide and ask questions. Private departures are available on request."},{"q":"Is the route accessible?","a":"Routes vary. Several walks use uneven lanes and steps. Tell us your requirements when you enquire and we will suggest a suitable route or adapt the walk."},{"q":"What happens if it rains?","a":"Walks run in light rain with covered stops built in. If conditions are unsafe we reschedule or refund in full."}]', 0, NULL, 1, 'published');
INSERT IGNORE INTO `destinations` (`slug`, `city`, `state`, `tagline`, `intro`, `image_url`, `gallery`, `neighbourhoods`, `best_time`, `about`, `food`, `architecture`, `local_stories`, `status`)
VALUES
  ('south-goa-temple-run', 'South Goa Temple Run', 'Goa', 'Goa''s sacred temples, far from the beaches.', 'Goa''s sacred temples, far from the beaches.', '/destinations/south-goa/mangeshi-premium.png', '["/destinations/south-goa/mangeshi-premium.png","/destinations/south-goa/Sapthakoteshwar-upscaled.webp"]', '["Nageshi, Mangeshi and Shanta Durga","Saptakoteshwar","Bhairoba Goa"]', '3 days', 'A 3 days heritage route through Nageshi, Mangeshi and Shanta Durga, Saptakoteshwar, Bhairoba Goa.', 'Local food traditions can be added to the route during planning.', 'Begin with two of Goa''s best-known temples and their distinctive architecture. Spend the day on the history and story of this ancient Shiva temple. Visit the local shrine, learn about village deity traditions, and wrap up the trip.', 'Goa''s sacred temples, far from the beaches.', 'published'),
  ('hampi-heritage-trail', 'Hampi Heritage Trail', 'Karnataka', 'Walk through the ruins of an empire.', 'Walk through the ruins of an empire.', '/destinations/hampi/Vijayanagara-premium.png', '["/destinations/hampi/Vijayanagara-premium.png","/destinations/hampi/Kishkindha-upscaled.webp","/destinations/hampi/Jain%20Temple-upscaled.webp","/destinations/hampi/0318f34cbdaaeaa3db7d70bddb30e561-upscaled.webp","/destinations/hampi/e02be3f1b23aa1169c0a5effbea43c7f-upscaled.webp"]', '["Vijayanagar","Kishkindha","Jain Prabhag","A slower day"]', '3-4 days', 'A 3-4 days heritage route through Vijayanagar, Kishkindha, Jain Prabhag, A slower day.', 'Local food traditions can be added to the route during planning.', 'Explore the royal and sacred centres of the old capital. Cross to the legendary landscape linked to the Ramayana. Discover Hampi''s lesser-known Jain heritage. Revisit favourite sites, sunrise viewpoints, and photography.', 'Walk through the ruins of an empire.', 'published'),
  ('coastal-karnataka-heritage', 'Coastal Karnataka Heritage', 'Karnataka coast', 'Temples, shores, and traditions along the Karnataka coast.', 'Temples, shores, and traditions along the Karnataka coast.', '/destinations/coastal-karnataka/Karwar-upscaled.webp', '["/destinations/coastal-karnataka/Karwar-upscaled.webp","/destinations/coastal-karnataka/Gokarna-upscaled.webp","/destinations/coastal-karnataka/Murudeshwar-upscaled.webp","/destinations/coastal-karnataka/Udupi-upscaled.webp","/destinations/coastal-karnataka/Karkala-upscaled.webp","/destinations/coastal-karnataka/264295f44288512c49cb4a74ff2b5690-upscaled.webp"]', '["Karwar","Gokarna","Murudeshwar","Udupi","Karkala"]', '4-5 days', 'A 4-5 days heritage route through Karwar, Gokarna, Murudeshwar, Udupi, Karkala.', 'Local food traditions can be added to the route during planning.', 'Start at the port town and its coastal history. Visit the pilgrimage town and its temples. See the seaside Shiva temple. Explore the temple town and its famous food traditions. Finish with the Jain monuments and heritage of the town.', 'Temples, shores, and traditions along the Karnataka coast.', 'published'),
  ('marathwada-heritage-trail', 'Marathwada Heritage Trail', 'Maharashtra and Telangana', 'Deccan history, from sultanates to the Nizams.', 'Deccan history, from sultanates to the Nizams.', '/destinations/marathwada/Solapur-upscaled.webp', '["/destinations/marathwada/Solapur-upscaled.webp","/destinations/marathwada/Hyderabad-upscaled.webp","/destinations/marathwada/Sambhajinagar-upscaled.webp","/destinations/marathwada/Pune-upscaled.webp"]', '["Solapur","Latur","Hyderabad","Chhatrapati Sambhajinagar, then return to Pune"]', '4 days', 'A 4 days heritage route through Solapur, Latur, Hyderabad, Chhatrapati Sambhajinagar, then return to Pune.', 'Local food traditions can be added to the route during planning.', 'Begin with the fort and the region''s old trade town. Continue through the heart of Marathwada. Spend the day on the monuments and old city of the Nizams. Close with the caves, forts, and tombs of the old Deccan capital.', 'Deccan history, from sultanates to the Nizams.', 'published'),
  ('western-maharashtra-heritage', 'Western Maharashtra Heritage', 'Maharashtra', 'The Maratha heartland, town by town.', 'The Maratha heartland, town by town.', '/destinations/western-maharashtra/Satara-upscaled.webp', '["/destinations/western-maharashtra/Satara-upscaled.webp","/destinations/western-maharashtra/wai-upscaled.webp","/destinations/western-maharashtra/Kolhapur-upscaled.webp","/destinations/western-maharashtra/Narsobachi%20Wadi-upscaled.webp","/destinations/western-maharashtra/karad-upscaled.webp"]', '["Pune, Wai and Satara","Kolhapur, Narsobachi Wadi and Karad"]', '2 days (please confirm)', 'A 2 days (please confirm) heritage route through Pune, Wai and Satara, Kolhapur, Narsobachi Wadi and Karad.', 'Local food traditions can be added to the route during planning.', 'Start with the old city, then travel to the ghats and hill towns of the Krishna valley. Visit the temple city, the riverside shrine, and end at the confluence town of Karad.', 'The Maratha heartland, town by town.', 'published'),
  ('northern-karnataka-heritage', 'Northern Karnataka Heritage', 'Karnataka', 'Where Indian temple architecture began.', 'Where Indian temple architecture began.', '/destinations/northern-karnataka/Badami-premium.png', '["/destinations/northern-karnataka/Badami-premium.png","/destinations/northern-karnataka/Aihole-premium.png","/destinations/northern-karnataka/Pattadakal-upscaled.webp"]', '["Badami","Aihole","Pattadakal","A flexible day"]', '3-4 days', 'A 3-4 days heritage route through Badami, Aihole, Pattadakal, A flexible day.', 'Local food traditions can be added to the route during planning.', 'Explore the cave temples and the old Chalukyan capital. See the early experimental temples, often called the cradle of temple architecture. Finish at the UNESCO-listed temple complex. Revisit sites or explore nearby villages.', 'Where Indian temple architecture began.', 'published');
INSERT IGNORE INTO `categories` (`slug`, `title`, `short`, `description`, `image_url`, `status`)
VALUES
  ('heritage-walks', 'Heritage Walks', 'Old quarters read street by street.', 'Slow, historian-led walks through old quarters where facades, doorways and street names carry the record.', '/src/assets/exp-heritage-walk-upscaled.webp', 'published'),
  ('food-walks', 'Food & Culinary Trails', 'Kitchens, bazaars and recipes with a past.', 'Trails that trace migration, trade and community through what a city cooks and how it eats.', '/src/assets/exp-food-upscaled.webp', 'published'),
  ('architecture-tours', 'Architecture Tours', 'Stone, brick and the ideas behind them.', 'Read buildings as documents — material, climate, patronage and the politics behind a facade.', '/src/assets/exp-architecture-upscaled.webp', 'published'),
  ('cultural-experiences', 'Cultural Experiences', 'Living traditions, met in person.', 'Music, craft, ritual and performance experienced with the practitioners who keep them alive.', '/src/assets/exp-cultural-upscaled.webp', 'published'),
  ('curated-journeys', 'Curated Journeys', 'Multi-day routes across regions.', 'Longer journeys that link cities, landscapes and communities into a single continuous narrative.', '/src/assets/exp-curated-upscaled.webp', 'published');
INSERT IGNORE INTO `stories` (`slug`, `category`, `title`, `excerpt`, `body`, `image_url`, `read_time`, `status`)
VALUES
  ('reading-a-facade', 'Architecture', 'How to Read a Facade Without a Guidebook', 'Cornices, brackets and window proportions record more about a building''s date and patron than most plaques do.', 'Cornices, brackets and window proportions record more about a building''s date and patron than most plaques do.', '/src/assets/story-architecture-upscaled.webp', '6 min read', 'published'),
  ('kitchens-that-remember', 'Food History', 'Kitchens That Remember: Migration on a Plate', 'Follow a single spice through four Indian cities and you have followed four centuries of trade, displacement and adaptation.', 'Follow a single spice through four Indian cities and you have followed four centuries of trade, displacement and adaptation.', '/src/assets/story-food-upscaled.webp', '8 min read', 'published'),
  ('the-last-looms', 'People & Communities', 'The Last Looms of a Weaving Lane', 'What happens to a craft neighbourhood when the market moves online and the next generation moves out.', 'What happens to a craft neighbourhood when the market moves online and the next generation moves out.', '/src/assets/story-people-upscaled.webp', '7 min read', 'published');
